// Social-Pip Telegram Pre-Send Check
// Telegram Bot API has generous limits
const item = $input.first().json;

const TELEGRAM_MAX_PER_MINUTE = 30;
const TELEGRAM_MAX_PER_SECOND = 1;
const TELEGRAM_MAX_MSG_LENGTH = 4096;

const accountStats = {
  messagesToday: item.messagesToday || 0,
  lastMessageAt: item.lastMessageAt ? new Date(item.lastMessageAt) : null,
  botStatus: item.botStatus || 'ACTIVE'
};

const errors = [];

// Telegram has no strict daily limits for bots
// But we implement our own reasonable limits
if (accountStats.messagesToday >= 500) {
  errors.push(`Daily limit reached: ${accountStats.messagesToday}/500`);
}

// Rate limit: 1 message per second
if (accountStats.lastMessageAt) {
  const timeSinceLastMsg = Date.now() - accountStats.lastMessageAt.getTime();
  if (timeSinceLastMsg < 1000) {
    errors.push('Wait at least 1 second between messages');
  }
}

// Message length check
if (item.content && item.content.length > TELEGRAM_MAX_MSG_LENGTH) {
  errors.push(`Message too long: ${item.content.length}/${TELEGRAM_MAX_MSG_LENGTH}`);
}

// Bot status
if (accountStats.botStatus === 'DISABLED' || accountStats.botStatus === 'BANNED') {
  errors.push(`Bot status: ${accountStats.botStatus}`);
}

if (errors.length > 0) {
  return { json: { valid: false, errors, accountStats } };
}

return { json: { valid: true, message: item, accountStats } };

const result = $input.first().json;

if (result.error) {
  return {
    json: {
      success: false,
      error: result.error,
      errorCode: result.error_code || 'UNKNOWN',
      platform: 'telegram'
    }
  };
}

return {
  json: {
    success: true,
    messageId: result.message_id,
    chatId: result.chat.id,
    publishedAt: new Date().toISOString(),
    platform: 'telegram'
  }
};
